export function validateBuy(qty, currentPrice, money, lotSize = 1) {
  if (qty <= 0) return { ok: false, error: 'Количество должно быть больше нуля' };
  if (qty * lotSize * currentPrice > money) return { ok: false, error: 'Недостаточно средств' };
  return { ok: true };
}

export function validateSell(qty, shares) {
  if (qty <= 0) return { ok: false, error: 'Количество должно быть больше нуля' };
  if (qty > shares) return { ok: false, error: 'Недостаточно лотов' };
  return { ok: true };
}

export function calcTotal(money, lots, currentPrice, lotSize = 1) {
  return money + lots * lotSize * currentPrice;
}

export function isDefeat(money, currentPrice, lots, lotSize = 1) {
  return money < lotSize * currentPrice && lots === 0;
}
