// Box-Muller transform: стандартное нормальное распределение
export function normalRandom() {
  let u, v;
  do { u = Math.random(); } while (u === 0);
  do { v = Math.random(); } while (v === 0);
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

// sigma = std(log-returns) - relative daily volatility, price-level independent
export function computeSigma(prices) {
  const logReturns = prices.slice(1).map((p, i) => Math.log(p / prices[i]));
  const mean = logReturns.reduce((a, b) => a + b, 0) / logReturns.length;
  const variance = logReturns.reduce((s, r) => s + (r - mean) ** 2, 0) / (logReturns.length - 1);
  return Math.sqrt(variance);
}

// Geometric Brownian Motion: relative volatility stays constant regardless of price level
export function nextPrice(prevPrice, sigma) {
  return prevPrice * Math.exp(sigma * normalRandom());
}
