  2: {
    title: 'Количество лотов',
    text: 'Введите количество вручную или выберите долю: 25%, 50% от максимума или «Макс» - для полной позиции.',
    target: '.dialog-input-row', combineWith: '.dialog-hint', rx: 8, pad: 8,
  },
  3: {
    title: 'Сумма сделки',
    text: 'Автоматически считается по формуле: лоты × размер лота × текущая цена. Проверьте перед покупкой.',
    target: '.dialog-field:last-child', rx: 6, pad: 8,
