  4: {
    title: 'Подтверждение покупки',
    text: 'Нажмите «Купить» - позиция откроется по текущей рыночной цене.',
    target: '.dbtn-buy', rx: 8, pad: 10,
  },
}

export default {
  name: 'GameView',
  components: { Line },

  computed: {
    isTestLevel() { return this.level === 0 },
    maxDeals()    { return this.isTestLevel ? MAX_DEALS_TEST : MAX_DEALS },
    completionContextHint() {
      if (this.isTestLevel) {
        return 'После каждой игры вы увидите итоговый размер счёта и динамику прибыли.'
      }
      if (this.isSimulatorMode) {
        return 'Посмотрите итоговый разбор своей торговли.'
      }
      if (this.level === 3) {
        return 'На следующей странице вы увидите полный разбор всех кейсов.'
      }
      return 'Продолжайте - по итогам всех кейсов вы увидите полный разбор.'
    },
    tutorialStepData() { return TUTORIAL_STEPS[this.tutorialStep] || { title: '', text: '' } },
    tutorialTotalSteps() {
      return Object.keys(TUTORIAL_STEPS).length + Object.keys(DIALOG_TUTORIAL_STEPS).length
    },
    globalTutorialStep() {
      const dLen = Object.keys(DIALOG_TUTORIAL_STEPS).length
      if (this.dialogTutorialStep > 0) return 6 + this.dialogTutorialStep
      if (this.tutorialStep > 6) return this.tutorialStep + dLen
      return this.tutorialStep
    },
    tutorialOverlayRects() {
      if (!this.spotlightRect) return null
      const sr = this.spotlightRect
      return [
        { left:'0', top:'0', right:'0', height:`${sr.y}px` },
        { left:'0', top:`${sr.y}px`, width:`${Math.max(0,sr.x)}px`, height:`${sr.height}px` },
        { left:`${sr.x+sr.width}px`, top:`${sr.y}px`, right:'0', height:`${sr.height}px` },
        { left:'0', top:`${sr.y+sr.height}px`, right:'0', bottom:'0' },
      ]
    },
    tutorialCardStyle() {
      if (!this.spotlightRect) return { left:'50%', transform:'translateX(-50%)', top:'50%' }
      const sr = this.spotlightRect
      const W = window.innerWidth, H = window.innerHeight
      const w = Math.min(460, W - 32)
      const l = Math.max(16, Math.min(W - w - 16, Math.round(sr.centerX - w / 2)))
      const below = H - sr.bottom > 180
      return {
        left: `${l}px`,
        ...(below ? { top:`${sr.bottom+14}px` } : { bottom:`${H-sr.top+14}px` }),
      }
    },
    tutorialArrowStyle() {
      if (!this.spotlightRect) return {}
      const sr = this.spotlightRect
      const W = window.innerWidth, H = window.innerHeight
      const w = Math.min(460, W - 32)
      const l = Math.max(16, Math.min(W - w - 16, Math.round(sr.centerX - w / 2)))
      const arrowLeft = Math.max(20, Math.min(w - 20, Math.round(sr.centerX - l)))
      const below = H - sr.bottom > 180
      const base = { position:'absolute', left:`${arrowLeft}px`, transform:'translateX(-50%)', width:0, height:0 }
      if (below) return { ...base, top:'-10px', borderLeft:'10px solid transparent', borderRight:'10px solid transparent', borderBottom:'10px solid white' }
      return { ...base, bottom:'-10px', borderLeft:'10px solid transparent', borderRight:'10px solid transparent', borderTop:'10px solid white' }
    },
    dialogTutorialStepData() { return DIALOG_TUTORIAL_STEPS[this.dialogTutorialStep] || { title: '', text: '' } },
    dialogOverlayRects() {
      if (!this.dialogSpotlightRect) return null
      const sr = this.dialogSpotlightRect
      return [
        { left:'0', top:'0', right:'0', height:`${sr.y}px` },
        { left:'0', top:`${sr.y}px`, width:`${Math.max(0,sr.x)}px`, height:`${sr.height}px` },
        { left:`${sr.x+sr.width}px`, top:`${sr.y}px`, right:'0', height:`${sr.height}px` },
        { left:'0', top:`${sr.y+sr.height}px`, right:'0', bottom:'0' },
      ]
    },
    dialogCardStyle() {
      if (!this.dialogSpotlightRect) return { left:'50%', transform:'translateX(-50%)', top:'40%' }
      const sr = this.dialogSpotlightRect
      const W = window.innerWidth, H = window.innerHeight
      const w = Math.min(460, W - 32)
      const l = Math.max(16, Math.min(W - w - 16, Math.round(sr.centerX - w / 2)))
      const below = H - sr.bottom > 180
      return { left:`${l}px`, ...(below ? { top:`${sr.bottom+14}px` } : { bottom:`${H-sr.top+14}px` }) }
    },
    dialogArrowStyle() {
      if (!this.dialogSpotlightRect) return {}
      const sr = this.dialogSpotlightRect
      const W = window.innerWidth, H = window.innerHeight
      const w = Math.min(460, W - 32)
      const l = Math.max(16, Math.min(W - w - 16, Math.round(sr.centerX - w / 2)))
      const arrowLeft = Math.max(20, Math.min(w - 20, Math.round(sr.centerX - l)))
      const below = H - sr.bottom > 180
      const base = { position:'absolute', left:`${arrowLeft}px`, transform:'translateX(-50%)', width:0, height:0 }
      if (below) return { ...base, top:'-10px', borderLeft:'10px solid transparent', borderRight:'10px solid transparent', borderBottom:'10px solid white' }
      return { ...base, bottom:'-10px', borderLeft:'10px solid transparent', borderRight:'10px solid transparent', borderTop:'10px solid white' }
    },
    levelName()  { return LEVEL_NAMES[this.level]  || '' },
    levelColor() { return LEVEL_COLORS[this.level] || 'var(--color-border)' },
    levelIconBg() {
      const map = { 0: 'var(--color-accent)', 1: 'var(--color-level-green)', 2: 'var(--color-level-blue)', 3: 'var(--color-level-gray-bg)', 4: 'var(--color-accent)' }
      return map[this.level] || 'var(--color-border)'
    },
    levelIcon()  { return LEVEL_ICONS[this.level]  || chartImg },
    levelDesc()  { return LEVEL_DESCS[this.level]  || '' },
    levelDescHtml() {
      return this.levelDesc
        .replace(/(прибыль\s)(\$[\d\s]+)/, '$1<span class="profit-highlight">$2</span>')
        .replace(/(\(-\$[\d\s]+\))/, '<span class="loss-highlight">$1</span>')
    },
    levelStartBalance() { return (this.startMoney[this.level] || 0) + (this.prevProfit[this.level] || 0) },
    activeDot()  { return this.level === 0 ? 3 : this.level === 4 ? 5 : this.level + 4 },

    assetName() { return marketData[this.selectedAsset]?.name || '' },
    currentLotSize() { return LOT_SIZES[this.selectedAsset] || 1 },
    sharesValue() { return this.shares * this.currentLotSize * this.currentPriceValue },
    totalPortfolio() { return calcTotal(this.money, this.shares, this.currentPriceValue, this.currentLotSize) },
    maxBuyQty() {
      const cost = this.currentLotSize * this.currentPriceValue
      return cost > 0 ? Math.floor(this.money / cost) : 0
    },
    canTrade() { return this.dealCount < this.maxDeals && !this.levelEnded },

    priceDeltaStr() {
      if (!this.prevPrice || this.prevPrice === this.currentPriceValue) return ''
      const d = ((this.currentPriceValue - this.prevPrice) / this.prevPrice * 100)
      return (d >= 0 ? '+' : '') + d.toLocaleString('ru-RU', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '% (за день)'
    },
    priceDeltaClass() {
      if (!this.prevPrice) return ''
      return this.currentPriceValue >= this.prevPrice ? 'delta-up' : 'delta-down'
    },
    currentTradeDiff() {
      if (this.dealCount < 1 || this.balanceHistory.length < 2) return null
      return this.totalPortfolio - this.balanceHistory[this.balanceHistory.length - 1]
    },
    lastTradeDiff() {
      if (this.dealCount < 1 || this.balanceHistory.length < 2) return null
      return this.balanceHistory[this.balanceHistory.length - 1] - this.balanceHistory[this.balanceHistory.length - 2]
    },
    sellBarStyle() {
      if (!this.sellTimerActive) return {}
      return {
        animationDelay: this.sellAnimDelay,
        animationPlayState: this.showExitMenu ? 'paused' : 'running'
      }
    },

    chartOptions() {
      return {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: ctx => ctx.parsed.y != null
                ? ctx.parsed.y.toLocaleString(undefined, { maximumFractionDigits: 4 }) : ''
            }
          }
        },
        scales: {
          x: { ticks: { color: cssVar('--color-axis', '#999'), font: { size: chartFontPx(12, 9) }, maxTicksLimit: 7, maxRotation: 0 }, grid: { color: cssVar('--color-border-subtle', '#eee') } },
          y: { ticks: { color: cssVar('--color-axis', '#999'), font: { size: chartFontPx(12, 9) } }, grid: { color: cssVar('--color-border-subtle', '#eee') } }
        }
      }
    },
    completionChartOptions() {
      return {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: { legend: { display: false }, tooltip: { enabled: false } },
        scales: {
          x: { display: true, ticks: { color: cssVar('--color-axis', '#999'), font: { size: chartFontPx(18, 13) }, maxTicksLimit: 8, maxRotation: 0 }, grid: { color: cssVar('--color-border-subtle', '#eee') } },
          y: { ticks: { color: cssVar('--color-axis', '#999'), font: { size: chartFontPx(18, 13) } }, grid: { color: cssVar('--color-border-subtle', '#eee') } }
        }
      }
    },
    chartStyles() { return { position: 'relative', height: '100%', width: '100%' } },
    chartPlugins() {
      const vm = this
      return [{
        id: 'tradeMarkerLines',
        afterDraw(chart) {
          if (!vm.tradeMarkers?.length) return
          if (!chart.chartArea) return
          const meta = chart.getDatasetMeta(0)
          if (!meta?.data) return
          const yScale = chart.scales?.y
          if (!yScale) return
          const ctx = chart.ctx
          const windowStart = vm.allLabels.length - chart.data.labels.length
          ctx.save()
          for (const m of vm.tradeMarkers) {
            const wi = m.allIdx - windowStart
            if (wi < 0 || wi >= chart.data.labels.length) continue
            const point = meta.data[wi]
            if (!point) continue
            const x = point.x
            const y = yScale.getPixelForValue(m.price)
            const color = m.type === 'buy' ? '#9E9E9E' : m.color
            ctx.setLineDash([4, 3])
            ctx.strokeStyle = color
            ctx.lineWidth = 1.5
            ctx.globalAlpha = 0.55
            ctx.beginPath()
            ctx.moveTo(x, chart.chartArea.top)
            ctx.lineTo(x, chart.chartArea.bottom)
            ctx.stroke()
            ctx.setLineDash([])
            ctx.globalAlpha = 1
            ctx.fillStyle = color
            ctx.beginPath()
            ctx.arc(x, y, 5, 0, Math.PI * 2)
            ctx.fill()
          }
          ctx.restore()
        }
      }]
    }
  },

  data() {
    return {
      MAX_DEALS,
      levelNotStarted: true,
      levelEnded: false,
      hasResult: false,
      level: 0,
      startMoney: { 0: 3000000, 1: 3000000, 2: 3000000, 3: 3000000, 4: 3000000 },
      prevProfit:  { 0: 0, 1: 3000000, 2: 0, 3: -1500000, 4: 0 },
      dealCount: 0,
      record: 0,
      money: 3000000,
      shares: 0,
      totalSum:      { 1: 0, 2: 0, 3: 0, 4: 0 },
      historyPoints: { 1: [], 2: [], 3: [], 4: [] },
      isSimulatorMode: false,
      balanceHistory: [],

      selectedAsset: null,
      historicalPrices: [],
      sigma: 0,
      currentPriceIndex: 0,
      animationTimer: null,
      isAnimating: false,
      prevPrice: 0,

      chartDataObj: markRaw({ labels: [], datasets: [{ data: [], borderColor: cssVar('--color-accent', '#AAC56F'), borderWidth: 2, pointRadius: 0, tension: 0.1, fill: true, backgroundColor: cssVar('--chart-fill-accent', 'rgba(170,197,111,0.08)') }] }),
      currentPriceValue: 0,

      allLabels: [],
      allPrices: [],
      tradeMarkers: [],
      activeWindow: 'полгода',
      timeWindows: [
        { key: 'неделя',  label: 'Неделя',  days: 7   },
        { key: 'месяц',   label: 'Месяц',   days: 30  },
        { key: 'полгода', label: 'Полгода', days: 182 },
        { key: 'год',     label: 'Год',     days: 365 },
        { key: 'все',     label: 'Все',     days: 0   }
      ],

      showBuyDialog: false,
      dialogQty: null,
      showExitMenu: false,

      sellTimerActive: false,
      sellTimerHandle: null,
      sellTimerStart: 0,
      sellAnimDelay: '0s',
      pauseBeginAt: 0,

      completionChartObj: null,
      completionTotal: 0,
      completionProfit: 0,

      tutorialStep: 0,
      spotlightRect: null,
      dialogTutorialStep: 0,
      dialogSpotlightRect: null,
      showingDealAlert: false,
    }
  },

  methods: {
    // ── Tutorial ─────────────────────────────────────────────────
    _updateSpotlight() {
      const step = TUTORIAL_STEPS[this.tutorialStep]
      if (!step?.target) { this.spotlightRect = null; return }
      const isMobile = window.innerWidth <= 700
      const sel = (isMobile && step.targetMobile) ? step.targetMobile : step.target
      const el = this.$el?.querySelector(sel)
      if (!el) { this.spotlightRect = null; return }
      const r = el.getBoundingClientRect()
      const pad = step.pad ?? 8
      if (step.combineWith) {
        const el2 = this.$el?.querySelector(step.combineWith)
        if (el2) {
          const r2 = el2.getBoundingClientRect()
          const cx = { left: Math.min(r.left, r2.left), top: Math.min(r.top, r2.top), right: Math.max(r.right, r2.right), bottom: Math.max(r.bottom, r2.bottom) }
          this.spotlightRect = {
            x: cx.left - pad, y: cx.top - pad,
            width: cx.right - cx.left + pad * 2, height: cx.bottom - cx.top + pad * 2,
            rx: step.rx ?? 4,
            centerX: (cx.left + cx.right) / 2,
            bottom: cx.bottom + pad, top: cx.top - pad,
          }
          return
        }
      }
      this.spotlightRect = {
        x: r.left - pad, y: r.top - pad,
        width: r.width + pad * 2, height: r.height + pad * 2,
        rx: step.rx ?? 8,
        centerX: r.left + r.width / 2,
        bottom: r.bottom + pad, top: r.top - pad,
      }
    },
    advanceTutorial() {
      if (this.tutorialStep === 6) { this.openBuyDialog(); return }
      if (this.tutorialStep === 7) { this.directSell(); return }
      if (this.tutorialStep >= Object.keys(TUTORIAL_STEPS).length) {
        this.tutorialStep = 0
      } else {
        this.tutorialStep++
      }
    },
    skipTutorial() { this.tutorialStep = 0 },
    _updateDialogSpotlight() {
      const step = DIALOG_TUTORIAL_STEPS[this.dialogTutorialStep]
      if (!step?.target) { this.dialogSpotlightRect = null; return }
      const dialogEl = this.$el?.querySelector('.modal-dialog-custom')
      if (!dialogEl) { this.dialogSpotlightRect = null; return }
      const pad = step.pad ?? 8
      const setRect = (left, top, right, bottom) => {
        this.dialogSpotlightRect = {
          x: left - pad, y: top - pad,
          width: right - left + pad * 2, height: bottom - top + pad * 2,
          rx: step.rx ?? 8, centerX: (left + right) / 2,
          bottom: bottom + pad, top: top - pad,
        }
      }
      if (step.combineAll) {
        const els = dialogEl.querySelectorAll(step.target)
        if (!els.length) { this.dialogSpotlightRect = null; return }
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
        els.forEach(el => { const r = el.getBoundingClientRect(); minX = Math.min(minX, r.left); minY = Math.min(minY, r.top); maxX = Math.max(maxX, r.right); maxY = Math.max(maxY, r.bottom) })
        setRect(minX, minY, maxX, maxY); return
      }
      const el = dialogEl.querySelector(step.target)
      if (!el) { this.dialogSpotlightRect = null; return }
      const r = el.getBoundingClientRect()
      if (step.combineWith) {
        const el2 = dialogEl.querySelector(step.combineWith)
        if (el2) {
          const r2 = el2.getBoundingClientRect()
          setRect(Math.min(r.left,r2.left), Math.min(r.top,r2.top), Math.max(r.right,r2.right), Math.max(r.bottom,r2.bottom)); return
        }
      }
      setRect(r.left, r.top, r.right, r.bottom)
    },
    advanceDialogTutorial() {
      if (this.dialogTutorialStep === 4) { this.confirmBuy(); return }
      if (this.dialogTutorialStep >= Object.keys(DIALOG_TUTORIAL_STEPS).length) {
        this.dialogTutorialStep = 0; this.dialogSpotlightRect = null
      } else {
        this.dialogTutorialStep++
        this.$nextTick(() => this._updateDialogSpotlight())
      }
    },

    // ── Navigation ──────────────────────────────────────────────
    openExitMenu() {
      this.stopAnimation()
      if (this.sellTimerHandle) { clearTimeout(this.sellTimerHandle); this.sellTimerHandle = null }
      if (this.sellTimerActive) this.pauseBeginAt = Date.now()
      this.showExitMenu = true
    },
    resumeGame() {
      this.showExitMenu = false
      this.resumeAnimation()
      if (this.sellTimerActive && this.sellTimerStart) {
        if (this.pauseBeginAt) {
          const pauseDuration = Date.now() - this.pauseBeginAt
          this.sellTimerStart += pauseDuration
          localStorage.setItem('sellTimerStart', this.sellTimerStart)
          this.pauseBeginAt = 0
        }
        const remaining = Math.max(100, 10000 - (Date.now() - this.sellTimerStart))
        this.sellTimerHandle = setTimeout(() => { this.directSell() }, remaining)
      }
    },
    goHome() { this.stopAnimation(); this.$router.push('/instructions?back=1') },
    goToResPage() {
      localStorage.setItem('record', this.record)
      localStorage.setItem('totalSum', JSON.stringify(this.totalSum))
      localStorage.setItem('hasResult', 'true')
      localStorage.setItem('historyPoints', JSON.stringify(this.historyPoints))
      if (this.selectedAsset) localStorage.setItem('selectedAsset', this.selectedAsset)
      if (this.isSimulatorMode) localStorage.setItem('gameMode', 'simulator')
      this.$router.push('/res')
    },

    // ── Game lifecycle ───────────────────────────────────────────
    endGame() {
      const { record, totalSum, historyPoints } = this
      localStorage.clear()
      Object.assign(this, { record, totalSum, dealCount: 0, level: 1, shares: 0, historyPoints })
      this.money = this.startMoney[1] + this.prevProfit[1]
    },
    restartGame() {
      this.stopAnimation()
      this.clearSellTimer()
      localStorage.clear()
      this.showExitMenu = false
      this.$router.push('/')
    },
    goToModeSelect() {
      this.stopAnimation()
      this.clearSellTimer()
      const asset = this.selectedAsset
      localStorage.clear()
      if (asset) localStorage.setItem('selectedAsset', asset)
      localStorage.setItem('level', '0')
      localStorage.setItem('levelEnded', 'true')
      this.showExitMenu = false
      this.$router.push('/mode')
    },
    restartLevel() {
      this.clearSellTimer()
      this.stopAnimation()
      this.dealCount = 0
      this.shares = 0
      this.money = this.startMoney[this.level] + this.prevProfit[this.level]
      this.levelEnded = false
      this.levelNotStarted = true
    },
    restartLevelFromMenu() {
      this.stopAnimation()
      this.clearSellTimer()
      const asset = this.selectedAsset || localStorage.getItem('selectedAsset')
      if (asset) this.selectedAsset = asset
      this.showExitMenu = false
      this.dealCount = 0
      this.shares = 0
      this.money = this.startMoney[this.level] + this.prevProfit[this.level]
      this.balanceHistory = []
      this.tradeMarkers = []
      this.levelNotStarted = true
      this.levelEnded = false
      this.completionChartObj = null
    },
    startLevel() {
      const asset = this.selectedAsset || localStorage.getItem('selectedAsset')
      if (!asset) { this.$router.push('/select'); return }
      this.selectedAsset = asset
      this.levelNotStarted = false
      this.levelEnded = false
      if (this.isTestLevel) this.tutorialStep = 1
      this.initLevel()
    },
    nextLevel() {
      this.dealCount = 0
      this.shares = 0
      this.balanceHistory = []
      this.money = this.startMoney[this.level] + this.prevProfit[this.level]
      this.levelNotStarted = true
      this.levelEnded = false
      this.completionChartObj = null
    },
    endLevelContinue() {
      if (this.isTestLevel) {
        this.$router.push('/mode')
        return
      }
      this.level++
      const maxLevel = this.isSimulatorMode ? 4 : 3
      if (this.level > maxLevel) {
        this.endGame()
        this.goToResPage()
      } else {
        this.nextLevel()
      }
    },
    finishLevelEarly() { this.endLevel() },

    // ── Level init ───────────────────────────────────────────────
    initLevel() {
      const assetData = marketData[this.selectedAsset]
      if (!assetData) return
      this.historicalPrices = assetData.prices
      this.sigma = computeSigma(this.historicalPrices.map(p => p.price))
      this.allLabels = this.historicalPrices.map(p => p.date)
      this.allPrices = this.historicalPrices.map(p => p.price)
      this.activeWindow = 'полгода'
      this.tradeMarkers = []
      localStorage.removeItem('walkPrices')
      localStorage.removeItem('walkLabels')

      const { labels, data } = this.getWindowedData()
      this.chartDataObj = markRaw({
        labels: labels.slice(),
        datasets: [
          { data: data.slice(), borderColor: cssVar('--color-accent', '#AAC56F'), backgroundColor: cssVar('--chart-fill-accent', 'rgba(170,197,111,0.08)'), borderWidth: 2, pointRadius: 0, tension: 0.1, fill: true }
        ]
      })

      const last = this.historicalPrices[this.historicalPrices.length - 1]
      this._lastDate = new Date(last.date)
      this.prevPrice = last.price
      this.currentPriceValue = last.price
      this.currentPriceIndex = 0
      this.shares = 0
      this.dealCount = 0
      this.money = this.startMoney[this.level] + this.prevProfit[this.level]
      this.levelEnded = false
      this.balanceHistory = [this.money]
      this.startAnimation()
    },

    // ── Chart / window ───────────────────────────────────────────
    getWindowedData() {
      const w = this.timeWindows.find(w => w.key === this.activeWindow)
      const days = w?.days ?? 0
      const start = days ? Math.max(0, this.allLabels.length - days) : 0
      return { labels: this.allLabels.slice(start), data: this.allPrices.slice(start) }
    },
    getMarkerData(windowStart, len) {
      const buyData = new Array(len).fill(null)
      const sellData = new Array(len).fill(null)
      const sellColors = new Array(len).fill('#66BB6A')
      for (const m of this.tradeMarkers) {
        const wi = m.allIdx - windowStart
        if (wi >= 0 && wi < len) {
          if (m.type === 'buy') {
            buyData[wi] = m.price
          } else {
            sellData[wi] = m.price
            sellColors[wi] = m.color
          }
        }
      }
      return { buyData, sellData, sellColors }
    },
    updateChart() {
      const chart = this.$refs.chart?.chart
      if (!chart?.data?.datasets?.[0]) return
      const { labels, data } = this.getWindowedData()
      chart.data.labels = labels
      chart.data.datasets[0].data = data
      chart.update('none')
    },
    changeWindow(key) { this.activeWindow = key; this.updateChart() },

    // ── Animation ────────────────────────────────────────────────
    nextWorkday(date) {
      const d = new Date(date)
      do { d.setDate(d.getDate() + 1) } while (d.getDay() === 0 || d.getDay() === 6)
      return d
    },
    formatDate(d) { return d.toISOString().slice(0, 10) },
    startAnimation() {
      this.stopAnimation()
      this.isAnimating = true
      this.animationTimer = setInterval(() => {
        try {
          this._lastDate = this.nextWorkday(this._lastDate)
          const newPrice = nextPrice(this.currentPriceValue, this.sigma)
          this.prevPrice = this.currentPriceValue
          this.currentPriceValue = newPrice
          this.currentPriceIndex++
          this.allLabels.push(this.formatDate(this._lastDate))
          this.allPrices.push(newPrice)
          const hl = this.historicalPrices.length
          localStorage.setItem('walkPrices', JSON.stringify(this.allPrices.slice(hl)))
          localStorage.setItem('walkLabels', JSON.stringify(this.allLabels.slice(hl)))
          this.updateChart()
          this.checkDefeat()
        } catch { /* ignore transient render errors */ }
      }, ANIMATION_INTERVAL_MS)
    },
    stopAnimation() {
      if (this.animationTimer) { clearInterval(this.animationTimer); this.animationTimer = null }
      this.isAnimating = false
    },
    resumeAnimation() { if (!this.levelEnded) this.startAnimation() },

    // ── Trade dialogs ────────────────────────────────────────────
    alert(text, type = 'info') {
      return VueSimpleAlert.alert('', '', type, { confirmButtonColor: cssVar('--color-accent', '#AAC56F'), html: text })
    },
    openBuyDialog() {
      this.clearSellTimer(); this.stopAnimation(); this.dialogQty = null; this.showBuyDialog = true
      if (this.isTestLevel && this.tutorialStep > 0) {
        this.$nextTick(() => { this.dialogTutorialStep = 1; this._updateDialogSpotlight() })
      }
    },
    startSellTimer(durationMs = 10000) {
      const elapsed = 10000 - durationMs
      this.sellTimerStart = Date.now() - elapsed
      this.sellAnimDelay = `-${(elapsed / 1000).toFixed(2)}s`
      this.sellTimerActive = true
      localStorage.setItem('sellTimerStart', this.sellTimerStart)
      this.sellTimerHandle = setTimeout(() => { this.directSell() }, durationMs)
    },
    clearSellTimer() {
      if (this.sellTimerHandle) { clearTimeout(this.sellTimerHandle); this.sellTimerHandle = null }
      this.sellTimerActive = false
      this.sellTimerStart = 0
      localStorage.removeItem('sellTimerStart')
    },
    async directSell() {
      this.clearSellTimer()
      if (this.shares <= 0) return
      this.money += this.shares * this.currentLotSize * this.currentPriceValue
      this.shares = 0
      this.dealCount++
      this.balanceHistory.push(this.totalPortfolio)
      const h = this.balanceHistory
      const sellColor = h.length >= 2 && h[h.length - 1] >= h[h.length - 2] ? '#66BB6A' : '#EF5350'
      this.tradeMarkers.push({ allIdx: this.allLabels.length - 1, price: this.currentPriceValue, type: 'sell', color: sellColor })
      await this.showDealAlert()
      if (this.isTestLevel && this.tutorialStep === 7) this.tutorialStep = 8
      this.checkLevelEnd()
      if (!this.levelEnded) this.resumeAnimation()
    },
    r5(n) { const r = Math.floor(n / 5) * 5; return r > 0 ? r : n },
    async showDealAlert() {
      const h = this.balanceHistory
      if (h.length < 2) return
      this.stopAnimation()
      const diff = h[h.length - 1] - h[h.length - 2]
      const sign = diff >= 0 ? '+' : '-'
      const abs  = Math.abs(diff).toLocaleString(undefined, { maximumFractionDigits: 0 })
      const type = diff >= 0 ? 'success' : 'error'
      const text = diff >= 0 ? 'Сделка была успешной' : 'Сделка была убыточной'
      this.showingDealAlert = true
      await this.alert(`${text}: ${sign}$${abs}`, type)
      this.showingDealAlert = false
    },
    cancelDialog() {
      this.showBuyDialog = false
      this.dialogQty = null
      this.dialogTutorialStep = 0; this.dialogSpotlightRect = null
      this.resumeAnimation()
    },
    confirmBuy() {
      const result = validateBuy(this.dialogQty, this.currentPriceValue, this.money, this.currentLotSize)
      if (!result.ok) { this.alert(result.error, 'warning'); return }
      this.money -= this.dialogQty * this.currentLotSize * this.currentPriceValue
      this.shares += this.dialogQty
      this.tradeMarkers.push({ allIdx: this.allLabels.length - 1, price: this.currentPriceValue, type: 'buy' })
      this.showBuyDialog = false; this.dialogQty = null
      this.dialogTutorialStep = 0; this.dialogSpotlightRect = null
      if (this.isTestLevel && this.tutorialStep > 0 && this.tutorialStep <= 6) this.tutorialStep = 7
      if (!this.levelEnded) { this.resumeAnimation(); this.startSellTimer() }
    },
    checkLevelEnd() {
      if (this.dealCount >= this.maxDeals) {
        this.alert((this.isSimulatorMode ? 'Игра пройдена!' : 'Кейс пройден!') + '<br>Итого: $' +
          this.totalPortfolio.toLocaleString(undefined, { maximumFractionDigits: 0 }), 'success')
        this.endLevel()
      }
    },
    checkDefeat() {
      if (isDefeat(this.money, this.currentPriceValue, this.shares, this.currentLotSize)) {
        this.alert('Недостаточно средств для покупки и нет лотов для продажи.', 'warning')
        this.endLevel()
      }
    },
    _initLevelFromSaved() {
      const assetData = marketData[this.selectedAsset]
      if (!assetData) return
      this.historicalPrices = assetData.prices
      this.sigma = computeSigma(this.historicalPrices.map(p => p.price))
      this.allLabels = this.historicalPrices.map(p => p.date)
      this.allPrices = this.historicalPrices.map(p => p.price)
      this.activeWindow = 'полгода'

      // Restore walk portion saved during active play
      const rawWalkPrices = localStorage.getItem('walkPrices')
      const rawWalkLabels = localStorage.getItem('walkLabels')
      if (rawWalkPrices && rawWalkLabels) {
        try {
          const wp = JSON.parse(rawWalkPrices)
          const wl = JSON.parse(rawWalkLabels)
          this.allPrices.push(...wp)
          this.allLabels.push(...wl)
          if (wp.length > 0) {
            this.currentPriceValue = wp[wp.length - 1]
            this._lastDate = new Date(wl[wl.length - 1])
            this.prevPrice = wp.length > 1 ? wp[wp.length - 2] : this.historicalPrices[this.historicalPrices.length - 1].price
            this.currentPriceIndex = wp.length
          }
        } catch { /* ignore corrupt data */ }
      }
      if (!rawWalkPrices) {
        const last = this.historicalPrices[this.historicalPrices.length - 1]
        this._lastDate = new Date(last.date)
        this.prevPrice = last.price
        this.currentPriceValue = last.price
        this.currentPriceIndex = 0
      }

      // Restore trade markers
      try {
        this.tradeMarkers = localStorage.getItem('tradeMarkers')
          ? JSON.parse(localStorage.getItem('tradeMarkers'))
          : []
      } catch { this.tradeMarkers = [] }

      const { labels, data } = this.getWindowedData()
      this.chartDataObj = markRaw({
        labels: labels.slice(),
        datasets: [
          { data: data.slice(), borderColor: cssVar('--color-accent', '#AAC56F'), backgroundColor: cssVar('--chart-fill-accent', 'rgba(170,197,111,0.08)'), borderWidth: 2, pointRadius: 0, tension: 0.1, fill: true }
        ]
      })
      // Animation stays paused - exit menu will be opened by caller
    },
    _restoreCompletionChart() {
      const startBal = this.startMoney[this.level] + this.prevProfit[this.level]
      if (this.level === 0) {
        const balData = this.balanceHistory
        if (!balData || !balData.length) return
        this.completionTotal = Number(localStorage.getItem('testCompletionTotal') || balData[balData.length - 1])
        this.completionProfit = this.completionTotal - startBal
        const balDataM = balData.map(v => +((v - startBal) / 1000000).toFixed(2))
        const ptColors = balData.map((v, i) => i === 0 ? 'transparent' : v >= balData[i - 1] ? '#66BB6A' : '#EF5350')
        this.completionChartObj = markRaw({
          labels: balDataM.map((_, i) => i),
          datasets: [{
            data: balDataM,
            borderColor: cssVar('--color-accent', '#AAC56F'),
            backgroundColor: 'transparent',
            borderWidth: 2,
            pointRadius: ptColors.map(c => c === 'transparent' ? 0 : 5),
            pointBackgroundColor: ptColors,
            pointBorderWidth: 0,
            fill: false
          }]
        })
        return
      }
      const hp = this.historyPoints[this.level]
      if (!hp || !hp[0] || !hp[0].data) return
      const rawData = hp[0].data.map(p => p.y)
      const balData = rawData.map(v => +((v - startBal) / 1000000).toFixed(2))
      this.completionTotal = this.totalSum[this.level] || 0
      this.completionProfit = this.completionTotal - startBal
      const ptColors = rawData.map((v, i) => i === 0 ? 'transparent' : v >= rawData[i - 1] ? '#66BB6A' : '#EF5350')
      this.completionChartObj = markRaw({
        labels: balData.map((_, i) => i),
        datasets: [{
          data: balData,
          borderColor: ({ 1: cssVar('--color-accent', '#AAC56F'), 2: cssVar('--color-market-blue', '#64A9DC'), 3: cssVar('--color-market-gray', '#B9BDC7'), 4: cssVar('--color-accent', '#AAC56F') })[this.level],
          backgroundColor: 'transparent',
          borderWidth: 2,
          pointRadius: ptColors.map(c => c === 'transparent' ? 0 : 5),
          pointBackgroundColor: ptColors,
          pointBorderWidth: 0,
          fill: false
        }]
      })
    },
    endLevel() {
      this.clearSellTimer()
      this.stopAnimation()
      this.levelEnded = true
      const total = calcTotal(this.money, this.shares, this.currentPriceValue, this.currentLotSize)
      this.completionTotal = total
      this.completionProfit = total - (this.startMoney[this.level] + this.prevProfit[this.level])
      if (this.shares > 0) this.balanceHistory.push(this.totalPortfolio)
      const balData = [...this.balanceHistory]
      if (!this.isTestLevel) {
        this.historyPoints[this.level] = [{
          fill: false, borderColor: cssVar('--color-accent', '#AAC56F'), borderWidth: 2, backgroundColor: cssVar('--color-accent', '#AAC56F'),
          data: balData.map((y, x) => ({ x, y }))
        }]
        this.totalSum[this.level] = total
        localStorage.setItem('historyPoints', JSON.stringify(this.historyPoints))
        localStorage.setItem('totalSum', JSON.stringify(this.totalSum))
      } else {
        localStorage.setItem('testCompletionTotal', String(total))
      }
      const startBal = this.startMoney[this.level] + this.prevProfit[this.level]
      const balDataM = balData.map(v => +((v - startBal) / 1000000).toFixed(2))
      const ptColors = balData.map((v, i) => i === 0 ? 'transparent' : v >= balData[i - 1] ? '#66BB6A' : '#EF5350')
      this.completionChartObj = markRaw({
        labels: balDataM.map((_, i) => i),
        datasets: [{
          data: balDataM,
          borderColor: ({ 0: cssVar('--color-accent', '#AAC56F'), 1: cssVar('--color-accent', '#AAC56F'), 2: cssVar('--color-market-blue', '#64A9DC'), 3: cssVar('--color-market-gray', '#B9BDC7'), 4: cssVar('--color-accent', '#AAC56F') })[this.level],
          backgroundColor: 'transparent',
          borderWidth: 2,
          pointRadius: ptColors.map(c => c === 'transparent' ? 0 : 5),
          pointBackgroundColor: ptColors,
          pointBorderWidth: 0,
          fill: false
        }]
      })
    }
  },

  mounted() {
    if (localStorage.money)         this.money         = Number(localStorage.money)
    if (localStorage.level)         this.level         = Number(localStorage.level)
    if (localStorage.record)        this.record        = Number(localStorage.record)
    if (localStorage.dealCount)     this.dealCount     = Number(localStorage.dealCount)
    if (localStorage.hasResult)     this.hasResult     = localStorage.hasResult === 'true'
    if (localStorage.totalSum)      this.totalSum      = JSON.parse(localStorage.totalSum)
    if (localStorage.historyPoints) this.historyPoints = JSON.parse(localStorage.historyPoints)
    if (localStorage.shares)         this.shares         = Number(localStorage.shares)
    if (localStorage.selectedAsset)  this.selectedAsset  = localStorage.selectedAsset
    if (localStorage.balanceHistory) this.balanceHistory = JSON.parse(localStorage.balanceHistory)
    const savedTutorial = localStorage.getItem('tutorialStep')
    if (savedTutorial !== null) this.tutorialStep = Number(savedTutorial)
    this.isSimulatorMode = localStorage.getItem('gameMode') === 'simulator'

    if (localStorage.levelEnded === 'true') {
      this.levelEnded = true
      this.levelNotStarted = false
      this._restoreCompletionChart()
      this.showExitMenu = true
    } else if (localStorage.levelNotStarted === 'false') {
      this.levelNotStarted = false
      this.levelEnded = false
      this._initLevelFromSaved()
      if (this.shares > 0) {
        const savedStart = Number(localStorage.getItem('sellTimerStart') || 0)
        if (savedStart) {
          const elapsed = Date.now() - savedStart
          const remaining = Math.max(100, 10000 - elapsed)
          this.sellTimerStart = savedStart
          this.sellAnimDelay = `-${Math.min(elapsed / 1000, 9.9).toFixed(2)}s`
          this.sellTimerActive = true
          this.sellTimerHandle = setTimeout(() => { this.directSell() }, remaining)
        } else {
          this.startSellTimer()
        }
      }
      // Pause any active sell timer - the exit menu will open immediately after
      if (this.sellTimerHandle) { clearTimeout(this.sellTimerHandle); this.sellTimerHandle = null }
      if (this.sellTimerActive) this.pauseBeginAt = Date.now()
      this.showExitMenu = true
    }
    this.$_resizeH = () => { if (this.tutorialStep > 0) this._updateSpotlight(); if (this.dialogTutorialStep > 0) this._updateDialogSpotlight() }
    window.addEventListener('resize', this.$_resizeH)
  },
  beforeUnmount() { this.clearSellTimer(); this.stopAnimation(); if (this.$_resizeH) window.removeEventListener('resize', this.$_resizeH) },

  watch: {
    money(v) {
      localStorage.money = v
      if (v > this.record) this.record = v
      localStorage.hasProgress = 'true'
    },
    level(v)            { localStorage.level = v },
    record(v)           { localStorage.record = v },
    dealCount(v)        { localStorage.dealCount = v },
    shares(v) {
      localStorage.shares = v
      if (v > 0 && !this.sellTimerActive && !this.levelEnded && !this.levelNotStarted) {
        this.startSellTimer()
      }
    },
    hasResult(v)        { localStorage.hasResult = v },
    levelNotStarted(v)  { localStorage.levelNotStarted = v },
    levelEnded(v)       { localStorage.levelEnded = v },
    selectedAsset(v)    { if (v) localStorage.setItem('selectedAsset', v) },
    totalSum:       { handler(v) { localStorage.totalSum       = JSON.stringify(v) }, deep: true },
    historyPoints:  { handler(v) { localStorage.historyPoints  = JSON.stringify(v) }, deep: true },
    balanceHistory: { handler(v) { localStorage.balanceHistory = JSON.stringify(v) }, deep: true },
    tradeMarkers:   { handler(v) { localStorage.setItem('tradeMarkers', JSON.stringify(v)) }, deep: true },
    tutorialStep(val) {
      localStorage.setItem('tutorialStep', val)
      if (val > 0) this.$nextTick(() => this._updateSpotlight()); else this.spotlightRect = null
    }
  }
}
</script>

